		} else {
			nums = append(nums, cur)
			cur = 0
		}
	}
	nums = append(nums, cur)
	if len(nums) >= 2 {
		*a = nums[0]
		*b = nums[1]
	}
	return 0, 0
}

func splitBySpace(s string) []string {
	var result []string
	cur := ""
	for _, c := range s {
		if c == ' ' {
			if len(cur) > 0 {
				result = append(result, cur)
				cur = ""
			}
		} else {
			cur += string(c)
		}
	}
	if len(cur) > 0 {
		result = append(result, cur)
	}
	return result
}
