		a--
		for pos < len(line) && line[pos] == ' ' {
			pos++
		}
		start = pos
		for pos < len(line) && pos < len(line) {
			pos++
		}
		b := 0
		for k := start; k < pos; k++ {
			b = b*10 + int(line[k]-'0')
		}
		b--
		adj[a] = append(adj[a], b)
		revAdj[b] = append(revAdj[b], a)
	}

	// We need to find states v such that there exists a path p1, p2, ..., pk
	// where:
	// - pi = v for some i
	// - f[p1] == 1 (assign)
	// - f[pk] == 2 (use)
	// - no pi (except p1) has f[pi] == 1

	// This means: v is on a path from some assign state to some use state,
	// and the path does not pass through any other assign state (except the start).

	// Approach:
	// 1. Find all states that can reach a use state (f==2) without passing through an assign state (f==1) after the start.
	// 2. More precisely: a state v is interesting if there exists an assign state a and a use state u such that there is a path a -> ... -> v -> ... -> u, and on this path, the only assign state is a.

	// Let's think differently:
	// A state v is interesting if:
	// - There exists an assign state a such that there is a path from a to v, and on this path, no assign state appears except a (i.e., v is reachable from a without passing through any other assign state).
	// - AND there exists a use state u such that there is a path from v to u, and on this path, no assign state appears (since if there were an assign state after v, it would break the condition).

	// So:
	// Step 1: Mark states that can reach a use state without passing through any assign state.
	//   Let canReachUse[i] = true if there is a path from i to some use state, and on this path, no assign state is encountered (except possibly i itself if i is an assign state, but we want paths that don't have assign states in the middle).
	//   Actually, we want: from v to u (use), the path should not contain any assign state. So we do a reverse BFS/DFS from all use states, but we stop when we hit an assign state (we don't go through assign states).

	// Step 2: Mark states that are reachable from an assign state without passing through any other assign state.
	//   Let reachableFromAssign[i] = true if there is an assign state a such that there is a path from a to i, and on this path, no assign state appears except a.
	//   We can do a BFS/DFS from all assign states, but we don't traverse through other assign states.

	// Then v is interesting if reachableFromAssign[v] && canReachUse[v].

	// Let's implement:

	// canReachUse: reverse BFS from all use states, not going through assign states.
	canReachUse := make([]bool, n)
	visited1 := make([]bool, n)
	queue := make([]int, 0)
	for i := 0; i < n; i++ {
		if f[i] == 2 {
			canReachUse[i] = true
			visited1[i] = true
			queue = append(queue, i)
		}
	}
	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		for _, v := range revAdj[u] {
			if !visited1[v] && f[v] != 1 { // don't go through assign states
				visited1[v] = true
				canReachUse[v] = true
				queue = append(queue, v)
			}
		}
	}

	// reachableFromAssign: BFS from all assign states, not going through other assign states.
	reachableFromAssign := make([]bool, n)
	visited2 := make([]bool, n)
	queue = make([]int, 0)
	for i := 0; i < n; i++ {
		if f[i] == 1 {
			reachableFromAssign[i] = true
			visited2[i] = true
			queue = append(queue, i)
		}
	}
	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		for _, v := range adj[u] {
			if !visited2[v] && f[v] != 1 { // don't go through other assign states
				visited2[v] = true
				reachableFromAssign[v] = true
				queue = append(queue, v)
			}
		}
	}

	// Output
	out := make([]byte, 0, n*2)
	for i := 0; i < n; i++ {
		if reachableFromAssign[i] && canReachUse[i] {
			out = append(out, '1')
		} else {
			out = append(out, '0')
		}
		if i < n-1 {
			out = append(out, '\n')
		}
	}
	os.Stdout.Write(out)
}
